import { useId, useLayoutEffect, useRef, type ReactNode } from 'react';
import { useControllableState } from '../../../primitives/use-controllable-state';
import './segmented-control.css';

export interface SegmentOption {
  value: string;
  label: ReactNode;
  icon?: ReactNode;
  disabled?: boolean;
}

export interface SegmentedControlProps {
  /** Names the group. Shown above it unless `hideLabel` is set. */
  label: ReactNode;
  hideLabel?: boolean;
  options: readonly SegmentOption[];
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  /** Form field name. Generated when omitted, so separate controls never share a group. */
  name?: string;
  size?: 's' | 'm';
  disabled?: boolean;
  className?: string;
}

/**
 * A small set of mutually exclusive options with a marker that slides to the selection.
 * Built on native radio buttons, so arrow keys, form submission and screen readers behave
 * exactly as they do for any radio group.
 */
export function SegmentedControl({
  label,
  hideLabel = false,
  options,
  value,
  defaultValue,
  onValueChange,
  name,
  size = 'm',
  disabled = false,
  className,
}: SegmentedControlProps) {
  const [selected, setSelected] = useControllableState({
    value,
    defaultValue: defaultValue ?? options[0]?.value ?? '',
    onChange: onValueChange,
  });
  const id = useId();
  const groupName = name ?? `${id}-segments`;
  const trackRef = useRef<HTMLDivElement>(null);

  useLayoutEffect(() => {
    const track = trackRef.current;
    if (!track) return;
    const place = () => {
      const input = track.querySelector<HTMLInputElement>('input:checked');
      const option = input?.closest<HTMLElement>('.atl-seg__option');
      if (!option) {
        track.style.setProperty('--atl-seg-w', '0px');
        return;
      }
      track.style.setProperty('--atl-seg-x', `${option.offsetLeft}px`);
      track.style.setProperty('--atl-seg-w', `${option.offsetWidth}px`);
    };
    place();
    const frame = requestAnimationFrame(() => track.setAttribute('data-ready', ''));
    const observer = new ResizeObserver(place);
    observer.observe(track);
    return () => {
      cancelAnimationFrame(frame);
      observer.disconnect();
    };
  }, [selected, options]);

  return (
    <div className={['atl-seg', className].filter(Boolean).join(' ')} data-size={size}>
      <span id={`${id}-label`} className={hideLabel ? 'atl-visually-hidden' : 'atl-seg__label'}>
        {label}
      </span>
      <div
        ref={trackRef}
        role="radiogroup"
        aria-labelledby={`${id}-label`}
        className="atl-seg__track"
      >
        <span className="atl-seg__marker" aria-hidden="true" />
        {options.map((option) => (
          <label
            key={option.value}
            className="atl-seg__option"
            data-disabled={option.disabled || disabled || undefined}
          >
            <input
              type="radio"
              name={groupName}
              value={option.value}
              checked={selected === option.value}
              disabled={option.disabled || disabled}
              onChange={() => setSelected(option.value)}
            />
            <span className="atl-seg__face">
              {option.icon ? (
                <span className="atl-seg__icon" aria-hidden="true">
                  {option.icon}
                </span>
              ) : null}
              {option.label}
            </span>
          </label>
        ))}
      </div>
    </div>
  );
}

@layer atlas.components {
  .atl-seg {
    display: inline-grid;
    gap: var(--space-2xs);
    max-width: 100%;
  }

  .atl-seg__label {
    font-weight: 600;
  }

  .atl-seg__track {
    position: relative;
    display: inline-flex;
    width: fit-content;
    max-width: 100%;
    padding: 3px;
    border-radius: var(--radius-panel);
    background: var(--shoal);
    box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--isobath) 60%, transparent);
  }

  .atl-seg__marker {
    position: absolute;
    top: 3px;
    bottom: 3px;
    left: 0;
    width: var(--atl-seg-w, 0px);
    border-radius: calc(var(--radius-panel) - 3px);
    background: var(--reef);
    box-shadow:
      inset 0 0 0 1px var(--edge),
      inset 0 -2px 0 var(--chart-magenta);
    transform: translateX(var(--atl-seg-x, 0px));
    pointer-events: none;
  }

  .atl-seg__track[data-ready] .atl-seg__marker {
    transition:
      transform var(--dur-current) var(--ease-current),
      width var(--dur-current) var(--ease-current);
  }

  .atl-seg__option {
    position: relative;
    z-index: 1;
    display: inline-grid;
    flex: 1 0 auto;
  }

  .atl-seg__option input {
    position: absolute;
    inset: 0;
    margin: 0;
    opacity: 0;
    cursor: pointer;
  }

  .atl-seg__option[data-disabled] input {
    cursor: not-allowed;
  }

  .atl-seg__face {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: var(--space-xs);
    min-height: 38px;
    padding: 0 var(--space-m);
    border-radius: calc(var(--radius-panel) - 3px);
    color: var(--ink-soft);
    font-weight: 550;
    white-space: nowrap;
    transition: color var(--dur-tick) var(--ease-anchor);
  }

  .atl-seg[data-size='s'] .atl-seg__face {
    min-height: 32px;
    padding: 0 var(--space-s);
    font-size: var(--step--1);
  }

  .atl-seg__option input:hover + .atl-seg__face {
    color: var(--ink);
  }

  .atl-seg__option input:checked + .atl-seg__face {
    color: var(--ink);
  }

  .atl-seg__option input:focus-visible + .atl-seg__face {
    outline: var(--focus-ring);
    outline-offset: 1px;
  }

  .atl-seg__option[data-disabled] .atl-seg__face {
    opacity: 0.5;
  }

  .atl-seg__icon {
    display: grid;
    place-items: center;
  }

  @media (forced-colors: active) {
    .atl-seg__marker {
      background: Highlight;
    }
    .atl-seg__option input:checked + .atl-seg__face {
      color: HighlightText;
    }
  }
}
